import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Contributing and wiki maintenance","description":"","frontmatter":{"pageId":"developers/contributing","contentRevision":1},"headers":[],"relativePath":"en/developers/contributing.md","filePath":"en/developers/contributing.md"}'),o={name:"en/developers/contributing.md"};function r(s,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="contributing-and-wiki-maintenance" tabindex="-1">Contributing and wiki maintenance <a class="header-anchor" href="#contributing-and-wiki-maintenance" aria-label="Permalink to &quot;Contributing and wiki maintenance&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Read repository instructions, status/diff and the relevant specification. Preserve other people&#39;s changes. Here Astra writes specifications/plans and one final review; the main Sol implements code and fixes. For substantial changes: approved design → plan → tests/implementation → one final review → verification.</p><p>Wiki maintenance is part of task completion. When changing features, behavioral fixes, config/CLI/API, installation, operations or recovery, update complete RU/EN articles, navigation and the reference inventory in the same task. Record sourcePaths and increment contentRevision in both versions and the manifest; give a concrete rationale if documentation is unaffected. A source snapshot does not authorize silently stale translations.</p><p>Run available checks and report pages/results/limitations. Keep secrets and internal handoff notes out of the published corpus. Commits verify the actual Git identity; push, PR and deployment require separate permission.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Dated plans and verification reports are historical material, not current functionality promises. Keep release versions aligned in Directory.Build.props, ClientInfo.Version and About.xml; change protocol only for incompatibility. Pages deployment is manual, not an ordinary push side effect.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./testing">Testing and acceptance</a></li><li><a href="./localization">Localization</a></li><li><a href="./../admins/updating">Updating server and clients</a></li></ul>',10)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
